CREATE OR REPLACE FUNCTION net._await_response(request_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
declare
    rec net._http_response;
begin
    while rec is null loop
        select *
        into rec
        from net._http_response
        where id = request_id;

        if rec is null then
            -- Wait 50 ms before checking again
            perform pg_sleep(0.05);
        end if;
    end loop;

    return true;
end;
$function$

CREATE OR REPLACE FUNCTION net._http_collect_response(request_id bigint, async boolean DEFAULT true)
 RETURNS net.http_response_result
 LANGUAGE plpgsql
AS $function$
declare
    rec net._http_response;
    req_exists boolean;
begin

    if not async then
        perform net._await_response(request_id);
    end if;

    select *
    into rec
    from net._http_response
    where id = request_id;

    if rec is null or rec.error_msg is not null then
        -- The request is either still processing or the request_id provided does not exist

        -- TODO: request in progress is indistinguishable from request that doesn't exist

        -- No request matching request_id found
        return (
            'ERROR',
            coalesce(rec.error_msg, 'request matching request_id not found'),
            null
        )::net.http_response_result;

    end if;

    -- Return a valid, populated http_response_result
    return (
        'SUCCESS',
        'ok',
        (
            rec.status_code,
            rec.headers,
            rec.content
        )::net.http_response
    )::net.http_response_result;
end;
$function$

CREATE OR REPLACE FUNCTION net.http_collect_response(request_id bigint, async boolean DEFAULT true)
 RETURNS net.http_response_result
 LANGUAGE plpgsql
AS $function$
begin
  raise notice 'The net.http_collect_response function is deprecated.';
  select net._http_collect_response(request_id, async);
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_cooperative_farm(p_claim_token text, p_user_id uuid, p_phone text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_farm record;
  v_already_has_manager boolean;
BEGIN
  SELECT id, phone, claim_token
    INTO v_farm
    FROM public.farms
   WHERE claim_token = p_claim_token
   FOR UPDATE;

  IF v_farm.id IS NULL THEN
    RAISE EXCEPTION 'CLAIM_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_farm.claim_token IS NULL THEN
    RAISE EXCEPTION 'CLAIM_ALREADY_USED' USING ERRCODE = 'P0003';
  END IF;

  IF v_farm.phone IS NOT NULL AND v_farm.phone <> p_phone THEN
    RAISE EXCEPTION 'CLAIM_PHONE_MISMATCH' USING ERRCODE = 'P0004';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.farm_managers WHERE farm_id = v_farm.id
  ) INTO v_already_has_manager;

  IF v_already_has_manager THEN
    RAISE EXCEPTION 'CLAIM_ALREADY_USED' USING ERRCODE = 'P0003';
  END IF;

  UPDATE public.farms
     SET phone       = p_phone,
         claim_token = NULL,
         updated_at  = now()
   WHERE id = v_farm.id;

  INSERT INTO public.farm_managers (user_id, farm_id, role)
  VALUES (p_user_id, v_farm.id, 'owner');

  RETURN v_farm.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_cooperative_with_officer(p_cooperative_name text, p_county text, p_sub_county text, p_ward text, p_primary_enterprise text, p_user_id uuid, p_email text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cooperative_id uuid;
BEGIN
  INSERT INTO public.cooperatives (
    cooperative_name, county, sub_county, ward, primary_enterprise
  ) VALUES (
    p_cooperative_name, p_county, p_sub_county, p_ward, p_primary_enterprise
  ) RETURNING id INTO v_cooperative_id;

  INSERT INTO public.cooperative_officers (
    cooperative_id, user_id, role, email
  ) VALUES (
    v_cooperative_id, p_user_id, 'admin', p_email
  );

  RETURN v_cooperative_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_farm_with_manager(p_farm_name text, p_owner_name text, p_phone text, p_county text, p_sub_county text, p_ward text, p_farm_types text[], p_primary_enterprise text, p_user_id uuid, p_subscription_end_date timestamp with time zone, p_email text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_farm_id uuid;
  v_existing record;
  v_already_has_manager boolean;
BEGIN
  -- Lock any existing row for this phone so two concurrent signups (or a
  -- signup racing a coop officer's farmer-mapping insert) can't both pass
  -- the check below.
  SELECT id, is_coop_managed, claim_token
    INTO v_existing
    FROM public.farms
   WHERE phone = p_phone
   FOR UPDATE;

  IF v_existing.id IS NOT NULL THEN
    IF v_existing.is_coop_managed IS TRUE AND v_existing.claim_token IS NOT NULL THEN
      -- This phone matches an unclaimed cooperative-mapped farm. Treat this
      -- signup as the claim: attach the verified user as owner instead of
      -- inserting a duplicate row.
      v_farm_id := v_existing.id;

      SELECT EXISTS (
        SELECT 1 FROM public.farm_managers WHERE farm_id = v_farm_id
      ) INTO v_already_has_manager;

      IF v_already_has_manager THEN
        -- Defensive: claim_token said "unclaimed" but a manager already
        -- exists. Don't silently reassign someone else's farm.
        RAISE EXCEPTION 'duplicate key value violates unique constraint "farms_phone_key"'
          USING ERRCODE = '23505';
      END IF;

      UPDATE public.farms
         SET owner_name           = p_owner_name,
             email                = COALESCE(p_email, email),
             claim_token          = NULL,
             farm_types           = p_farm_types,
             primary_enterprise   = COALESCE(primary_enterprise, p_primary_enterprise),
             subscription_tier    = 'smallholder',
             subscription_end_date = p_subscription_end_date,
             updated_at           = now()
       WHERE id = v_farm_id;

      INSERT INTO public.farm_managers (user_id, farm_id, role)
      VALUES (p_user_id, v_farm_id, 'owner');

      RETURN v_farm_id;
    ELSE
      -- Phone already belongs to a standalone or already-claimed farm.
      -- Surface the same error shape the app already handles (23505).
      RAISE EXCEPTION 'duplicate key value violates unique constraint "farms_phone_key"'
        USING ERRCODE = '23505';
    END IF;
  END IF;

  -- No existing farm for this phone — normal fresh signup.
  INSERT INTO public.farms (
    farm_name, owner_name, phone, email, county, sub_county, ward,
    is_active, subscription_tier, subscription_end_date,
    farm_types, primary_enterprise
  ) VALUES (
    p_farm_name, p_owner_name, p_phone, p_email, p_county, p_sub_county, p_ward,
    true, 'smallholder', p_subscription_end_date,
    p_farm_types, p_primary_enterprise
  ) RETURNING id INTO v_farm_id;

  INSERT INTO public.farm_managers (user_id, farm_id, role)
  VALUES (p_user_id, v_farm_id, 'owner');

  RETURN v_farm_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_farm_with_manager(p_farm_name text, p_owner_name text, p_phone text, p_county text, p_sub_county text, p_ward text, p_farm_types text[], p_primary_enterprise text, p_user_id uuid, p_subscription_end_date timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_farm_id uuid;
  v_existing_farm_id uuid;
BEGIN
  -- Is the current user already linked to a farm? Just return it (idempotent).
  SELECT farm_id INTO v_existing_farm_id
  FROM public.farm_managers WHERE user_id = p_user_id LIMIT 1;

  IF v_existing_farm_id IS NOT NULL THEN
    RETURN v_existing_farm_id;
  END IF;

  -- Orphan case: a farm exists with this phone (e.g. coop-managed, pre-registered)
  -- but isn't linked to this user yet. Link it instead of inserting a duplicate.
  SELECT id INTO v_existing_farm_id FROM public.farms WHERE phone = p_phone LIMIT 1;

  IF v_existing_farm_id IS NOT NULL THEN
    INSERT INTO public.farm_managers (user_id, farm_id, role)
    VALUES (p_user_id, v_existing_farm_id, 'owner')
    ON CONFLICT DO NOTHING;
    RETURN v_existing_farm_id;
  END IF;

  INSERT INTO public.farms (farm_name, owner_name, phone, county, sub_county, ward,
    is_active, subscription_tier, subscription_end_date, farm_types, primary_enterprise)
  VALUES (p_farm_name, p_owner_name, p_phone, p_county, p_sub_county, p_ward,
    true, 'smallholder', p_subscription_end_date, p_farm_types, p_primary_enterprise)
  RETURNING id INTO v_farm_id;

  INSERT INTO public.farm_managers (user_id, farm_id, role)
  VALUES (p_user_id, v_farm_id, 'owner');

  RETURN v_farm_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_calf_same_farm()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.calf_id IS NOT NULL THEN
    IF (SELECT farm_id FROM cows WHERE id = NEW.calf_id)
       <> (SELECT farm_id FROM cows WHERE id = NEW.cow_id) THEN
      RAISE EXCEPTION 'calf_id must belong to the same farm as cow_id';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_cow_parents_same_farm()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.dam_id IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.dam_id IS DISTINCT FROM OLD.dam_id OR NEW.farm_id IS DISTINCT FROM OLD.farm_id) THEN
    IF (SELECT farm_id FROM cows WHERE id = NEW.dam_id) IS DISTINCT FROM NEW.farm_id THEN
      RAISE EXCEPTION 'dam_id must belong to the same farm';
    END IF;
  END IF;

  IF NEW.sire_id IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.sire_id IS DISTINCT FROM OLD.sire_id OR NEW.farm_id IS DISTINCT FROM OLD.farm_id) THEN
    IF (SELECT farm_id FROM cows WHERE id = NEW.sire_id) IS DISTINCT FROM NEW.farm_id THEN
      RAISE EXCEPTION 'sire_id must belong to the same farm';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_ruminant_parents_same_farm()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.dam_id IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.dam_id IS DISTINCT FROM OLD.dam_id OR NEW.farm_id IS DISTINCT FROM OLD.farm_id) THEN
    IF (SELECT farm_id FROM small_ruminants WHERE id = NEW.dam_id) IS DISTINCT FROM NEW.farm_id THEN
      RAISE EXCEPTION 'dam_id must belong to the same farm';
    END IF;
  END IF;

  IF NEW.sire_id IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.sire_id IS DISTINCT FROM OLD.sire_id OR NEW.farm_id IS DISTINCT FROM OLD.farm_id) THEN
    IF (SELECT farm_id FROM small_ruminants WHERE id = NEW.sire_id) IS DISTINCT FROM NEW.farm_id THEN
      RAISE EXCEPTION 'sire_id must belong to the same farm';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_passport_code(p_cooperative_id uuid, p_year integer DEFAULT NULL::integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year    integer := COALESCE(p_year, EXTRACT(YEAR FROM now())::integer);
  v_seq     integer;
  v_code    text;
BEGIN
  SELECT COUNT(*) + 1
  INTO v_seq
  FROM public.coffee_passports
  WHERE cooperative_id = p_cooperative_id
    AND EXTRACT(YEAR FROM created_at)::integer = v_year;

  v_code := 'FI-' || v_year::text || '-' || LPAD(v_seq::text, 4, '0');
  RETURN v_code;
END;
$function$

